func groupAnagrams(strs []string) [][]string {
	// 边界检查
	ans:=[][]string{}
	if len(strs)<1{
		return ans
	}
	var (
		word string
		val string
	)
	ansRec:=map[string][]string{}
	for _,word=range strs{
		val = helper(word)
		if _,ok:=ansRec[val];ok{
			ansRec[val] = append(ansRec[val],word)
		}else{
			ansRec[val] = []string{word}
		}
	}
	for _,v:=range ansRec{
		ans = append(ans, v)
	}
	return ans
}

